update public.marketplace_legal_documents
set
  title = 'เงื่อนไขการเผยแพร่สินค้า',
  summary = 'หลักเกณฑ์ด้านสิทธิ ความถูกต้องของข้อมูล และการตรวจสอบร่วมกันก่อนเผยแพร่สินค้า',
  content_html = '<ul><li>ผู้ขายมีสิทธิหรือได้รับอนุญาตให้เผยแพร่และจำหน่ายข้อความ รูปภาพ วิดีโอ เสียง ฟอนต์ แบบฝึกหัด และไฟล์ที่ใช้ในสินค้า</li><li>เนื้อหาสินค้าเป็นไปตามหลักเกณฑ์ด้านลิขสิทธิ์ เครื่องหมายการค้า สิทธิส่วนบุคคล และการคุ้มครองข้อมูลเด็ก นักเรียน หรือบุคคลอื่น</li><li>รายละเอียด ราคา เงื่อนไขการใช้งาน และสิ่งที่ผู้ซื้อจะได้รับแสดงไว้อย่างถูกต้องและครบถ้วน</li><li>หากมีข้อสงสัยหรือข้อร้องเรียน แพลตฟอร์มและผู้ขายจะร่วมกันตรวจสอบข้อมูลและดำเนินการตามนโยบายที่เกี่ยวข้อง</li></ul>',
  updated_at = now()
where document_type = 'product_submission_terms'
  and version = '1.0'
  and title = 'ข้อตกลงการส่งสินค้าเข้าตรวจ'
  and content_html = '<ul><li>ฉันเป็นเจ้าของหรือได้รับอนุญาตให้เผยแพร่และจำหน่ายข้อความ รูปภาพ วิดีโอ เสียง ฟอนต์ แบบฝึกหัด และไฟล์ทั้งหมดในสินค้านี้</li><li>สินค้านี้ไม่ละเมิดลิขสิทธิ์ เครื่องหมายการค้า สิทธิส่วนบุคคล และไม่มีข้อมูลเด็ก นักเรียน หรือบุคคลอื่นโดยไม่ได้รับอนุญาต</li><li>รายละเอียด ราคา เงื่อนไขการใช้งาน และสิ่งที่ผู้ซื้อจะได้รับเป็นข้อมูลจริง ถูกต้อง และครบถ้วน</li><li>ฉันรับผิดชอบต่อข้อเรียกร้องที่เกิดจากสินค้าของตน และยินยอมให้แพลตฟอร์มขอหลักฐาน ระงับสินค้า พักยอด นำสินค้าออก หรือคืนเงินตามนโยบายและกฎหมาย</li></ul>';
